import boto3
from botocore.exceptions import ClientError
import os

def check_image_for_unsafe_content(image_path: str, min_confidence: float = 60.0) -> dict:
    """
    Checks an image for unsafe or policy-sensitive visual content using Amazon Rekognition.
    Returns a dictionary indicating if unsafe content was found and details of detected moderation labels.
    """
    rekognition = boto3.client('rekognition')

    if not os.path.exists(image_path):
        raise FileNotFoundError(f"Image file not found at {image_path}")

    with open(image_path, 'rb') as image_file:
        image_bytes = image_file.read()

    try:
        response = rekognition.detect_moderation_labels(
            Image={'Bytes': image_bytes},
            MinConfidence=min_confidence
        )

        moderation_labels = response.get('ModerationLabels', [])
        detected = [
            {
                'name': label['Name'],
                'confidence': label['Confidence'],
                'parent_category': label.get('ParentName', 'Uncategorized')
            }
            for label in moderation_labels
        ]

        return {
            'is_unsafe': len(detected) > 0,
            'detected_labels': detected
        }
    except ClientError as e:
        raise RuntimeError(f"Amazon Rekognition API call failed: {e}")
